unit VariantCoerceDemo;

interface

uses Variants;

function Total(const A, B : Variant) : Variant;

implementation

function Total(const A, B : Variant) : Variant;
begin
  // Looks like addition; behaves differently depending on whether
  // A and B carry numeric tags or string tags. '12' + '34' yields
  // the Variant string '1234', not 46. '12' + 34 yields the Variant
  // integer 46 (string promoted to int via DecimalSeparator -- locale
  // dependent!). Real-world bug pattern in legacy Indy payload code.
  Result := A + B;
end;

end.
